  // END REVIEWED EVENT DETAILS
  function eventFacts(event,{locale='en',now=Date.now()}={}){
    const text=value=>typeof value==='string'?value.trim().slice(0,1500):'';
    const rows=value=>Array.isArray(value)?value.slice(0,100):[];
    const extra=event?.extraData||{},community=extra.communityday||{},spotlight=extra.spotlight||{},raid=extra.raidbattles||{};
    const reviewed=reviewedEventDetails.events[String(event?.eventID||event?.id||'')];
    const reviewedUsable=reviewed?.bonuses?.length&&Number.isFinite(Date.parse(reviewed.checkedAt));
    const bonuses=[...rows(community.bonuses).map(b=>text(b?.text)),text(spotlight.bonus),...rows(event?.bonuses).map(b=>text(b?.text))].filter(Boolean);
    const encounters=[...rows(community.spawns),...rows(spotlight.list)].map(p=>text(p?.name)).filter(Boolean);
    const bosses=rows(raid.bosses).map(p=>text(p?.name)).filter(Boolean);
    const research=rows(community.specialresearch).map(step=>({name:text(step?.name),tasks:rows(step?.tasks).map(task=>({text:text(task?.text),reward:text(task?.reward?.text)})).filter(task=>task.text)})).filter(step=>step.name||step.tasks.length);
    const bonusSource=reviewedUsable?{url:reviewed.source,checkedAt:reviewed.checkedAt,stale:reviewed.status==='last-known'||now-Date.parse(reviewed.checkedAt)>48*3600000,language:'en'}:bonuses.length?{url:event.link||'https://github.com/bigfoott/ScrapedDuck',checkedAt:null,stale:false,language:'en'}:null;
    return{bonusSource,bonuses:reviewedUsable?reviewed.bonuses:[...new Set(bonuses)],caveats:reviewedUsable?reviewed.caveats:rows(community.bonusDisclaimers).map(text).filter(Boolean),encounters:[...new Set(encounters)],bosses:[...new Set(bosses)],research};
  }
  function fallbackEventData(){return{events:reviewedEventDetails.feed||[],raids:[],fetchedAt:Date.parse(reviewedEventDetails.generatedAt)||0,raidsUnavailable:true,stale:true,sourceFallback:true};}
  function safeHttpsUrl(value){
    const raw=String(value||'');
    if(!/^https:\/\/[^\s\\]+$/i.test(raw)||/[\u0000-\u001f\u007f]/.test(raw))return'';
    try{
      const url=new URL(raw);
      if(url.protocol!=='https:'||!url.hostname||url.username||url.password)return'';
      return url.href;
    }catch{return'';}
  }
